"""Engineering rules. Universal / language / framework scoped; retrieved progressively, never dumped.
`must`+overridable=False rules cannot be disabled by project overrides."""


def R(key, domain, severity, statement, rationale, *, scope="universal", langs=(), fws=(), when="", detect=(), overridable=True, refs=()):
    return dict(key=key, domain=domain, severity=severity, statement=statement, rationale=rationale, scope=scope,
                languages=list(langs), frameworks=list(fws), applies_when=when, detect=[dict(re=r, msg=m) for r, m in detect],
                overridable=overridable, refs=list(refs))


RULES = [
 # ---- security & secrets (non-overridable)
 R("sec-no-hardcoded-secrets", "security", "must", "Never put secrets (keys, tokens, passwords) in source, logs, tests or examples; load them from env/secret stores.",
   "Committed secrets leak through history, forks and CI logs and cannot be revoked by deleting the line.", when="writing config, auth, API clients, tests",
   overridable=False, refs=["CWE-798", "OWASP A07:2021"],
   detect=[(r"(?i)\b(?:api[_-]?key|secret|token|passwd|password)\b\s*[:=]\s*[\"'][A-Za-z0-9_\-/+=]{16,}[\"']", "possible hardcoded secret"),
           (r"AKIA[0-9A-Z]{16}", "AWS access key id"), (r"-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----", "private key in source")]),
 R("sec-parameterized-sql", "security", "must", "Build SQL with bound parameters, never string formatting/concatenation of user input.",
   "String-built queries are the classic SQL-injection vector.", when="database queries", overridable=False, refs=["CWE-89"],
   detect=[(r"(?i)\.execute\(\s*f[\"'].*(select|insert|update|delete)", "f-string SQL passed to execute()"),
           (r"(?i)\.execute\(\s*[\"'][^\"']*(select|insert|update|delete)[^\"']*[\"']\s*(%|\+|\.format)", "string-formatted SQL"),
           (r"(?i)(query|exec)\(\s*`[^`]*(select|insert|update|delete)[^`]*\$\{", "template-literal SQL")]),
 R("sec-no-shell-injection", "security", "must", "Run subprocesses with an argument list (no shell); never interpolate untrusted input into a command string.",
   "Shell metacharacters in input become commands.", when="spawning processes", overridable=False, refs=["CWE-78"],
   detect=[(r"subprocess\.\w+\([^)]*shell\s*=\s*True", "subprocess with shell=True"), (r"\bos\.system\(", "os.system"),
           (r"child_process\.exec\(\s*[`\"'][^)]*(\$\{|\+)", "child_process.exec with interpolation")]),
 R("sec-tls-verify", "security", "must", "Never disable TLS certificate verification; fix the trust store or pin the CA instead.",
   "verify=False turns HTTPS into unauthenticated transport.", when="HTTP clients", overridable=False, refs=["CWE-295"],
   detect=[(r"verify\s*=\s*False", "TLS verification disabled"), (r"InsecureSkipVerify:\s*true", "Go InsecureSkipVerify"),
           (r"rejectUnauthorized\s*:\s*false", "Node rejectUnauthorized:false"), (r"NODE_TLS_REJECT_UNAUTHORIZED\s*=\s*[\"']?0", "NODE_TLS_REJECT_UNAUTHORIZED=0")]),
 R("sec-no-unsafe-deserialize", "security", "must", "Don't deserialize untrusted data with pickle/yaml.load/eval; use JSON or safe loaders.",
   "These formats can execute code on load.", when="parsing external data", overridable=False, refs=["CWE-502"], langs=["python"],
   detect=[(r"\bpickle\.loads?\(", "pickle on possibly untrusted data"), (r"yaml\.load\((?![^)]*SafeLoader)", "yaml.load without SafeLoader"),
           (r"(?<![\w.])eval\(", "eval()"), (r"(?<![\w.])exec\(", "exec()")]),
 R("sec-validate-at-boundary", "security", "should", "Validate and bound all external input (type, size, range, path) at the trust boundary; reject early with a precise error.",
   "Prevents injection, traversal and resource exhaustion.", when="request handlers, CLIs, file import"),
 R("sec-path-traversal", "security", "must", "Resolve user-supplied paths against a base directory and verify the result stays inside it; skip symlinks when extracting archives.",
   "../ and symlinks escape the intended directory (zip-slip).", when="file upload/extract/serve", overridable=False, refs=["CWE-22"]),
 R("sec-password-hashing", "security", "must", "Hash passwords with a slow salted KDF (argon2id/scrypt/bcrypt); compare tokens in constant time.",
   "Fast hashes (md5/sha1/sha256) are brute-forceable; == leaks timing.", when="authentication", overridable=False, refs=["CWE-916"],
   detect=[(r"hashlib\.(md5|sha1)\(", "md5/sha1 (not for passwords or integrity against attackers)")]),
 R("sec-least-privilege", "security", "should", "Run services as non-root with the minimum filesystem/network permissions; drop capabilities.", "Limits blast radius.", when="deployment, containers, systemd"),
 R("sec-dependency-trust", "security", "should", "Pin and review new dependencies (maintenance, license, install scripts) before adding; prefer the standard library for small needs.",
   "Supply-chain and maintenance risk grows with every dependency.", when="adding a dependency"),
 # ---- error handling
 R("err-no-silent-except", "error-handling", "should", "Don't swallow exceptions: catch specific types, handle or re-raise with context, never bare `except:` / empty catch.",
   "Silent failures turn bugs into data corruption.", when="try/except", langs=["python"],
   detect=[(r"^\s*except\s*:\s*$", "bare except"), (r"except\s+Exception\s*:\s*\n\s*pass", "except Exception: pass")]),
 R("err-js-empty-catch", "error-handling", "should", "Never leave a catch block empty; log with context or rethrow.", "Hides failures.", langs=["javascript", "typescript"],
   detect=[(r"catch\s*(\([^)]*\))?\s*\{\s*\}", "empty catch block")]),
 R("err-go-check-errors", "error-handling", "must", "Check every returned error; wrap with %w and context (fmt.Errorf(\"op: %w\", err)).", "Unchecked errors cause nil derefs and lost data.",
   langs=["go"], overridable=False),
 R("err-fail-fast-clear", "error-handling", "should", "Fail fast with an actionable message: what failed, why (if known), and what to do next.", "Faster diagnosis for users and for Claude.", when="CLI/API errors"),
 R("err-timeouts", "error-handling", "must", "Every network/IO call needs a timeout and bounded retries with backoff+jitter; make retried operations idempotent.",
   "Unbounded waits hang services; blind retries amplify outages.", when="HTTP clients, RPC, DB", overridable=False),
 R("err-js-await", "error-handling", "must", "Always await or .catch() promises; never fire-and-forget an async call without a handler.", "Unhandled rejections crash Node and hide errors.", langs=["javascript", "typescript"]),
 # ---- testing
 R("test-regression-first", "testing", "should", "Reproduce a bug with a failing test before fixing, then keep the test as regression coverage.", "Proves the fix and prevents reappearance.", when="bug fixing"),
 R("test-no-fake-green", "testing", "must", "Never weaken, skip, or delete a test to make it pass; fix the code or explain the test is wrong.", "Green tests that don't test anything are worse than red.", overridable=False),
 R("test-real-boundaries", "testing", "should", "Prefer testing real behavior (subprocess/CLI, HTTP handler, DB) over mocking internals; inject clocks/randomness instead of patching.", "Mock-heavy tests pass while the product is broken.", when="writing tests"),
 R("test-deterministic", "testing", "should", "Tests must be deterministic: no sleeps for sync, no network, fixed seeds, temp dirs.", "Flaky tests destroy trust.", when="writing tests"),
 # ---- architecture / simplicity / maintainability
 R("arch-simplest-thing", "simplicity", "should", "Implement the simplest design that meets the stated requirement; add abstractions only for duplication that exists today.",
   "Speculative generality adds code to maintain and bugs to find.", when="designing features"),
 R("arch-separate-io-logic", "architecture", "should", "Separate data collection / IO from pure logic and from presentation so each is testable alone.", "Enables fast unit tests and reuse.", when="structuring modules"),
 R("arch-no-global-state", "architecture", "should", "Avoid mutable module-level state and import-time side effects; pass dependencies explicitly.", "Hidden state breaks tests and concurrency.", langs=["python", "javascript", "typescript"]),
 R("maint-small-functions", "maintainability", "may", "Keep functions focused; extract when you need a comment to explain a block.", "Readability and reviewability.", when="refactoring"),
 R("maint-names", "maintainability", "should", "Name things for what they mean in the domain; avoid abbreviations and generic names (data, tmp, util).", "Names are the primary documentation.", when="any code"),
 R("maint-match-conventions", "maintainability", "must", "Match the surrounding code's style, structure and naming; don't reformat or refactor unrelated code in the same change.", "Small reviewable diffs.", when="editing existing code"),
 R("maint-delete-dead", "maintainability", "may", "Remove dead code and unused dependencies instead of commenting them out.", "VCS keeps history.", when="cleanup"),
 # ---- performance
 R("perf-measure-first", "performance", "must", "Profile before optimizing; change one thing and compare before/after on a representative workload.", "Guesses optimize the wrong thing.", when="performance work"),
 R("perf-n-plus-one", "performance", "should", "Batch queries/requests (joins, IN clauses, bulk APIs) instead of per-item loops; add indexes for filtered columns.", "N+1 dominates latency.", when="data access"),
 R("perf-bounded-memory", "performance", "should", "Stream large inputs and bound queues/caches; never load unbounded data into memory.", "OOM under real load.", when="file/data processing"),
 R("perf-py-no-concat-loop", "performance", "may", "Build strings with join / lists, not repeated += in hot loops.", "Quadratic behavior in some cases.", langs=["python"]),
 # ---- API compatibility / dependencies / licensing / docs
 R("api-no-breaking-silently", "api-compat", "must", "Don't change public function signatures, CLI flags, schemas or exit codes without a deprecation path or version bump.", "Downstream users break silently.", when="changing public interfaces"),
 R("api-version-and-document", "api-compat", "should", "Version APIs and document behavior changes in a changelog.", "Consumers can plan upgrades.", when="releasing"),
 R("dep-lock-and-minimal", "dependencies", "should", "Commit lockfiles, pin direct versions, remove unused dependencies, and run the ecosystem's audit tool.", "Reproducible builds and fewer CVEs.", when="managing dependencies"),
 R("dep-deprecated-apis", "dependencies", "should", "Replace deprecated APIs when touching code; check the library's changelog for the target version.", "Deprecated calls get removed.", when="upgrading"),
 R("lic-verify-before-use", "licensing", "must", "Before copying third-party code/assets, confirm the license permits your distribution model and keep required notices (THIRD_PARTY_NOTICES).",
   "License violations are legal liabilities.", when="vendoring code or assets", overridable=False),
 R("lic-no-unlicensed", "licensing", "must", "Treat code/assets with no explicit license as all-rights-reserved; don't copy them.", "No license = no permission.", overridable=False),
 R("doc-explain-why", "documentation", "should", "Document why (constraints, trade-offs, non-obvious decisions) and how to run/verify; don't narrate what the code obviously does.", "Code already says what.", when="writing docs/comments"),
 R("doc-runnable-examples", "documentation", "should", "README examples must be copy-paste runnable and tested.", "Broken examples destroy trust.", when="writing docs"),
 # ---- language / framework specific
 R("py-datetime-aware", "language", "should", "Use timezone-aware datetimes (datetime.now(timezone.utc)); datetime.utcnow() is deprecated.", "Naive/aware mixing raises TypeError and utcnow is deprecated since 3.12.", scope="language", langs=["python"],
   detect=[(r"datetime\.utcnow\(\)", "deprecated datetime.utcnow()")]),
 R("py-mutable-default", "language", "must", "Never use mutable default arguments (def f(x=[])); use None and create inside.", "The default is shared between calls.", scope="language", langs=["python"],
   detect=[(r"def\s+\w+\([^)]*=\s*(\[\]|\{\}|set\(\))", "mutable default argument")]),
 R("py-pathlib-context", "language", "should", "Use pathlib and `with` blocks for files; build paths from __file__ not cwd.", "Portable, leak-free.", scope="language", langs=["python"]),
 R("py-tempfile", "language", "must", "Use tempfile.mkstemp/NamedTemporaryFile/TemporaryDirectory, never tempfile.mktemp.", "mktemp is racy.", scope="language", langs=["python"], overridable=False,
   detect=[(r"tempfile\.mktemp\(", "tempfile.mktemp is insecure")]),
 R("js-no-innerhtml", "language", "must", "Don't assign untrusted strings to innerHTML/document.write; use textContent or a sanitizer/framework escaping.", "XSS.", scope="language", langs=["javascript", "typescript"], overridable=False, refs=["CWE-79"],
   detect=[(r"\.innerHTML\s*=(?!=)", "innerHTML assignment"), (r"document\.write\(", "document.write"), (r"dangerouslySetInnerHTML", "React dangerouslySetInnerHTML")]),
 R("js-deprecated-node", "language", "should", "Avoid deprecated Node APIs: new Buffer(), fs.exists, url.parse, util.isArray.", "Removed or security-flagged.", scope="language", langs=["javascript", "typescript"],
   detect=[(r"new Buffer\(", "new Buffer() is deprecated"), (r"\bfs\.exists\(", "fs.exists is deprecated")]),
 R("js-strict-equality", "language", "should", "Prefer const/let and === over var and ==.", "Avoids hoisting/coercion bugs.", scope="language", langs=["javascript", "typescript"],
   detect=[(r"(?<![=!<>])==(?!=)", "loose equality ==")]),
 R("go-context-first", "language", "should", "Pass context.Context as the first parameter for blocking calls; honor cancellation; set http.Server timeouts.", "Prevents leaks and slowloris.", scope="language", langs=["go"]),
 R("go-deprecated", "language", "should", "Use io/os instead of deprecated io/ioutil; use crypto/rand not math/rand for secrets.", "Deprecated since Go 1.16.", scope="language", langs=["go"],
   detect=[(r"io/ioutil", "io/ioutil is deprecated")]),
 R("react-keys-effects", "framework", "should", "Give list items stable keys; keep effects minimal with correct dependency arrays; derive state instead of syncing it.", "Prevents stale UI and render loops.", scope="framework", fws=["react"]),
 R("react-a11y", "framework", "should", "Use semantic elements, labels and keyboard-operable controls; verify focus and contrast.", "Accessibility is correctness.", scope="framework", fws=["react", "html"]),
 R("fastapi-async-blocking", "framework", "must", "Don't call blocking IO in `async def` endpoints; use async clients or run_in_threadpool.", "Blocks the event loop for all requests.", scope="framework", fws=["fastapi"]),
]
